// se-scorecards.tsx
// Generated by Sigil — do not edit manually

"use client";

import { useRouter } from "next/navigation";
import { useState, useMemo } from "react";
import { toast } from "sonner";
import { Download, GitCompare, Loader2, Search } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from "@/components/ui/sheet";
import { Toaster } from "@/components/ui/sonner";
import { DataTable } from "@/components/data-table";
import { SigilChart } from "@/components/sigil-chart";
import { ScorecardHeatmap } from "@/components/scorecard-heatmap";
import { useScorecard } from "@/hooks/use-scorecard";
import { useDimensionScore } from "@/hooks/use-dimensionscore";
import { useLensContext } from "@/lib/lens-context";
import type { ChartConfig } from "@/components/ui/chart";

export default function SeScorecards() {
  const router = useRouter();
  const { currentLensId, currentLensName } = useLensContext();
  const [searchScorecard, setSearchScorecard] = useState("");

  const { data: scorecard, isLoading: scorecardLoading } = useScorecard();
  const { data: allDimensionScores } = useDimensionScore();
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [compareOpen, setCompareOpen] = useState(false);

  const toggleSelection = (id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else if (next.size < 5) next.add(id);
      else toast("Select up to 5 repos to compare");
      return next;
    });
  };

  const selectedScorecards = useMemo(
    () => (scorecard ?? []).filter((sc) => selectedIds.has(sc.id)),
    [scorecard, selectedIds],
  );

  const COMPARE_COLORS = [
    "oklch(0.623 0.214 259.815)",
    "oklch(0.6 0.118 184.704)",
    "oklch(0.828 0.189 84.429)",
    "oklch(0.769 0.188 70.08)",
    "oklch(0.646 0.222 41.116)",
  ];

  const compareData = useMemo(() => {
    if (selectedScorecards.length < 2) return { radar: [], dimensions: [] as string[], config: {} as ChartConfig, table: [] as { dimension: string; [key: string]: unknown }[] };
    const scIds = new Set(selectedScorecards.map((sc) => sc.id));
    const relevantScores = allDimensionScores.filter((ds) => scIds.has(ds.scorecard_id ?? ""));
    const dimSet = new Set(relevantScores.map((ds) => ds.dimension_name ?? "Unknown"));
    const dimensions = [...dimSet].sort();
    const scoreLookup = new Map<string, Map<string, number>>();
    for (const ds of relevantScores) {
      const scId = ds.scorecard_id ?? "";
      if (!scoreLookup.has(scId)) scoreLookup.set(scId, new Map());
      scoreLookup.get(scId)!.set(ds.dimension_name ?? "Unknown", Number(ds.score ?? 0));
    }
    const radar = dimensions.map((dim) => {
      const point: Record<string, unknown> = { dimension: dim };
      for (const sc of selectedScorecards) {
        point[sc.repo_name ?? sc.id] = scoreLookup.get(sc.id)?.get(dim) ?? 0;
      }
      return point;
    });
    const config: ChartConfig = {};
    selectedScorecards.forEach((sc, i) => {
      config[sc.repo_name ?? sc.id] = { label: sc.repo_name ?? sc.id, color: COMPARE_COLORS[i % COMPARE_COLORS.length] };
    });
    const table = dimensions.map((dim) => {
      const row: Record<string, unknown> = { dimension: dim };
      for (const sc of selectedScorecards) {
        row[sc.repo_name ?? sc.id] = scoreLookup.get(sc.id)?.get(dim) ?? null;
      }
      return row;
    });
    return { radar, dimensions, config, table };
  }, [selectedScorecards, allDimensionScores]);

  const exportCsv = () => {
    const rows = lensFilteredScorecards.filter((item) => {
      if (!searchScorecard) return true;
      const q = searchScorecard.toLowerCase();
      return Object.values(item).some((v) => String(v).toLowerCase().includes(q));
    });
    if (!rows.length) { toast("No data to export"); return; }
    const headers = ["Repo", "Overall Score", "Lens", "Scored At"];
    const csvRows = [
      headers.join(","),
      ...rows.map((sc) =>
        [sc.repo_name, Number(sc.overall ?? 0), sc.lens_name, sc.scored_at]
          .map((v) => `"${String(v ?? "").replace(/"/g, '""')}"`)
          .join(",")
      ),
    ];
    const blob = new Blob([csvRows.join("\n")], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "scorecards.csv";
    a.click();
    URL.revokeObjectURL(url);
    toast.success(`Exported ${rows.length} scorecards`);
  };

  const lensFilteredScorecards = (scorecard ?? []).filter(
    (sc) => !currentLensId || sc.lens_id === currentLensId,
  );

  if (scorecardLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <>
    <div className="flex flex-col gap-5 p-6">
      <div className="flex flex-row gap-4 justify-between items-center">
        <div className="flex flex-col gap-1">
          <h1 className="text-2xl font-semibold tracking-tight text-foreground">Scorecards</h1>
          <p className="text-sm text-muted-foreground">Compare repos across dimensions — scores colored by range</p>
        </div>
        <div className="flex flex-row gap-2">
          <Button variant="outline" onClick={exportCsv}>
            <Download className="mr-2 h-4 w-4" />
            Export CSV
          </Button>
          <Button
            variant="default"
            disabled={selectedIds.size < 2}
            onClick={() => setCompareOpen(true)}
          >
            <GitCompare className="mr-2 h-4 w-4" />
            Compare{selectedIds.size > 0 ? ` (${selectedIds.size})` : ""}
          </Button>
        </div>
      </div>
      <div className="relative">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <Input type="search" placeholder="Search scorecards by repo name..." className="w-full pl-9 [&::-webkit-search-cancel-button]:hidden [&::-webkit-search-decoration]:hidden" value={searchScorecard} onChange={(e) => setSearchScorecard(e.target.value)} />
      </div>
      <Card>
        <CardHeader>
          <CardTitle>All Scorecards</CardTitle>
          <CardDescription>Scored repos ranked by overall score in {currentLensName || "selected"} lens</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex flex-row gap-4 items-center">
            <p className="text-sm text-muted-foreground">Score key:</p>
            <Badge variant="outline" className="border-emerald-500/30 bg-emerald-500/10 text-emerald-600 dark:text-emerald-400">8-10 Strong</Badge>
            <Badge variant="outline" className="border-amber-500/30 bg-amber-500/10 text-amber-600 dark:text-amber-400">5-7 Average</Badge>
            <Badge variant="destructive">0-4 Weak</Badge>
            <Badge variant="default">— Unscored</Badge>
          </div>
          <DataTable
            data={lensFilteredScorecards
              .filter((item) => {
                if (!searchScorecard) return true;
                const q = searchScorecard.toLowerCase();
                return Object.values(item).some((v) => String(v).toLowerCase().includes(q));
              })}
            columns={[
              {
                id: "select",
                header: () => null,
                cell: ({ row }: { row: { original: { id: string } } }) => (
                  <div onClick={(e) => e.stopPropagation()}>
                    <Checkbox
                      checked={selectedIds.has(row.original.id)}
                      onCheckedChange={() => toggleSelection(row.original.id)}
                    />
                  </div>
                ),
              },
              { accessorKey: "repo_name", header: "Repo" },
              { accessorKey: "overall", header: "Overall" },
              {
                accessorKey: "lens_name",
                header: "Lens",
                cell: ({ row }: { row: { getValue: (k: string) => unknown } }) => {
                  const v = String(row.getValue("lens_name") ?? "");
                  const variants: Record<string, string> = { "Leadership": "warning", "Security": "danger", "Community": "success", "Maintainability": "info", "Engineering": "info", "Overall": "default", "Innovation": "success", "Adoption": "warning", "Product": "default" };
                  const variant = variants[v] ?? variants[v.toLowerCase()] ?? "default";
                  return <Badge variant={variant === "danger" ? "destructive" : variant === "success" || variant === "warning" || variant === "info" ? "outline" : "secondary"} className={
                    variant === "success" ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-400" :
                    variant === "warning" ? "border-amber-500/30 bg-amber-500/10 text-amber-400" :
                    variant === "info" ? "border-blue-500/30 bg-blue-500/10 text-blue-400" :
                    variant === "danger" ? "" : ""
                  }>{v}</Badge>;
                },
              },
              { accessorKey: "scored_at", header: "Scored" },
            ]}
            emptyMessage="No matching results found."
            onRowClick={(row) => router.push(`/repo-detail/${(row as { id: string }).id}`)}
          />
        </CardContent>
      </Card>
      <Card>
        <CardHeader>
          <CardTitle>Dimension Heatmap</CardTitle>
          <CardDescription>Per-dimension scores by repo — select a lens to compare</CardDescription>
        </CardHeader>
        <CardContent>
          <ScorecardHeatmap />
        </CardContent>
      </Card>
      <Card>
        <CardHeader>
          <CardTitle>Score Distribution</CardTitle>
          <CardDescription>Overall scores across all scored repos</CardDescription>
        </CardHeader>
        <CardContent>
          <SigilChart
            type="bar"
            xKey="repo"
            height={250}
            showGrid
            dataKeys={["score"]}
            config={{
              score: { label: "Overall Score", color: "var(--chart-1)" },
            }}
            data={lensFilteredScorecards
              .filter((sc) => sc.overall != null)
              .sort((a, b) => Number(b.overall ?? 0) - Number(a.overall ?? 0))
              .slice(0, 15)
              .map((sc) => ({ repo: sc.repo_name ?? "Unknown", score: Number(sc.overall ?? 0) }))}
          />
        </CardContent>
      </Card>
    </div>
    <Sheet open={compareOpen} onOpenChange={setCompareOpen}>
      <SheetContent side="right" className="overflow-y-auto" style={{ maxWidth: Math.min(672 + Math.max(0, selectedScorecards.length - 3) * 120, 912) }}>
        <SheetHeader>
          <SheetTitle>Compare Scorecards</SheetTitle>
          <SheetDescription>
            {selectedScorecards.map((sc) => sc.repo_name).join(" vs ")}
          </SheetDescription>
        </SheetHeader>
        <div className="flex flex-col gap-6 p-4">
          <Card>
            <CardHeader>
              <CardTitle className="text-base">Overall Scores</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex flex-row gap-3 justify-center">
                {selectedScorecards.map((sc, i) => (
                  <div
                    key={sc.id}
                    className="flex flex-col items-center gap-1 rounded-lg px-5 py-3"
                    style={{ backgroundColor: COMPARE_COLORS[i % COMPARE_COLORS.length] }}
                  >
                    <div className="text-3xl font-bold text-white">
                      {Number(sc.overall ?? 0).toFixed(1)}
                    </div>
                    <div className="text-xs font-medium text-white/80">{sc.repo_name}</div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
          {compareData.radar.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle className="text-base">Dimension Radar</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex items-center justify-center">
                  <SigilChart
                    type="radar"
                    xKey="dimension"
                    height={300}
                    showLegend
                    dataKeys={selectedScorecards.map((sc) => sc.repo_name ?? sc.id)}
                    config={compareData.config}
                    data={compareData.radar}
                  />
                </div>
              </CardContent>
            </Card>
          )}
          {compareData.table.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle className="text-base">Dimension Scores</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b">
                        <th className="text-left py-2 pr-4 font-medium text-muted-foreground">Dimension</th>
                        {selectedScorecards.map((sc, i) => (
                          <th
                            key={sc.id}
                            className="text-center py-2 px-3 font-medium"
                            style={{ color: COMPARE_COLORS[i % COMPARE_COLORS.length] }}
                          >
                            {sc.repo_name}
                          </th>
                        ))}
                        {selectedScorecards.length === 2 && (
                          <th className="text-center py-2 px-3 font-medium text-muted-foreground">Delta</th>
                        )}
                      </tr>
                    </thead>
                    <tbody>
                      {compareData.table.map((row) => {
                        const scores = selectedScorecards.map(
                          (sc) => row[sc.repo_name ?? sc.id] as number | null,
                        );
                        const delta =
                          selectedScorecards.length === 2 && scores[0] != null && scores[1] != null
                            ? Number(scores[0]) - Number(scores[1])
                            : null;
                        return (
                          <tr key={row.dimension as string} className="border-b last:border-0">
                            <td className="py-2 pr-4 text-muted-foreground">{row.dimension as string}</td>
                            {scores.map((score, i) => (
                              <td key={i} className="text-center py-2 px-3 font-mono">
                                {score != null ? Number(score).toFixed(1) : "—"}
                              </td>
                            ))}
                            {delta !== null && (
                              <td className="text-center py-2 px-3">
                                <Badge
                                  variant="outline"
                                  className={
                                    delta > 0
                                      ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-400"
                                      : delta < 0
                                        ? "border-red-500/30 bg-red-500/10 text-red-400"
                                        : ""
                                  }
                                >
                                  {delta > 0 ? "+" : ""}{delta.toFixed(1)}
                                </Badge>
                              </td>
                            )}
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </CardContent>
            </Card>
          )}
        </div>
      </SheetContent>
    </Sheet>
    <Toaster />
    </>
  );
}
